import{_ as i,o as t,c as r,a3 as o}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"Appendix: Common Priority Structures","description":"","frontmatter":{"translationSource":{"title":"附录 常见的优先级结构设计","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=IlngKiLhDJAlZSX3Qv1eGF","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/appendix-common-priority-structures"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/appendix-common-priority-structures"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/appendix-common-priority-structures"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/appendix-common-priority-structures"}]]},"headers":[],"relativePath":"appendix-common-priority-structures.md","filePath":"logistics/src/page-IlngKiLhDJAlZSX3Qv1eGF.md"}'),a={name:"appendix-common-priority-structures.md"};function s(n,e,l,p,u,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<div class="logistics-content"><h1 id="appendix-common-priority-structures" tabindex="-1">Appendix: Common Priority Structures <a class="header-anchor" href="#appendix-common-priority-structures" aria-label="Permalink to &quot;Appendix: Common Priority Structures&quot;">​</a></h1><blockquote><p>Source page ID: <code>IlngKiLhDJAlZSX3Qv1eGF</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=IlngKiLhDJAlZSX3Qv1eGF" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><span id="source-block-sNZTojqUdxbXh5mI6F3Lp9"></span></p><h4 id="common-priority-structures" tabindex="-1">Common Priority Structures <a class="header-anchor" href="#common-priority-structures" aria-label="Permalink to &quot;Common Priority Structures&quot;">​</a></h4><p>Besides placing a Converger at a stash output, several other structures produce priority:</p><ol><li><span class="mark-purple">In a Reactor Crucible, </span><span class="mark-purple"><strong>externally supplied inputs preferentially output; internally produced Liquid Xiranite preferentially reacts; other materials preferentially output</strong></span><span class="mark-purple">.</span></li><li><span class="mark-purple">When a Splitter points into a Converger, </span><span class="mark-purple"><strong>the line connected to the Converger later has lower priority</strong></span><span class="mark-purple">.</span></li><li><span class="mark-purple">With Convergers at outputs of containers such as </span><span class="mark-purple"><strong>unloaders, crucibles, or even unloaders, container output has lower priority than the passing belt</strong></span><span class="mark-purple">. This is not universal: Conduit Outlets and Fluid Tanks lack the behavior. Also, an unpowered Reactor Crucible can act as an inferior substitute for a Splitter pointing into a Converger.</span></li><li></li></ol><blockquote><p><a href="/endfield-skydoc/input-output-merge-priority-theory">Input / Output / Merge Priority Theory: A Brief Explanation</a></p></blockquote><p><span id="source-block-H0ozGwHnWV5wiu8Ejp9HGN"></span></p><h4 id="priority-output-for-large-flows" tabindex="-1">Priority Output for Large Flows <a class="header-anchor" href="#priority-output-for-large-flows" aria-label="Permalink to &quot;Priority Output for Large Flows&quot;">​</a></h4><p>Transport limits mean that strict priority for solids above 30/m or fluids above 120/m requires splitting across multiple belts/pipes, applying the earlier priority structure independently to each, then merging corresponding outputs. This is inconvenient, so alternatives include:</p><ol><li>Replace priority output with splitting structures; see Section 2.4 and elsewhere, outside this section&#39;s scope.</li><li>Use fluid instead of solid. Prioritizing 120 Cuprium Gas is equivalent to prioritizing 240 solid Cuprium, provided all 240 becomes gas.</li><li>Prioritize only part of the flow. Essentially similar to splitting, but included here because it uses a priority structure.</li></ol><p>Examples follow.</p><details><summary>Using a Stash to Prioritize a Solid Flow of 30–60</summary><p><img src="/endfield-skydoc/logistics/src/assets/images/img-3cc3864874cd487e.q90-757e0cc6ecb3b760.webp" alt="Appendix: Common Priority Structures"></p><p>For balanced production in the illustration, the Separator Core–Cuprium Canister branch consumes about 46 Cuprium and needs priority. Two Cuprium lines enter a stash, with two outputs directly feeding the Moulding Unit and a low-priority branch feeding Shredding Unit–Reactor Crucible. While the Moulding Unit is unblocked, both Cuprium lines prioritize it and nothing goes to shredding. Separator Core blocking thus propagates back to the Moulding Unit&#39;s Cuprium. Once Cuprium fills up, 30 flow diverts to shredding while another 30 stays in the stash. After Separator Core is consumed, Cuprium again prioritizes moulding.</p><p>Questions to consider; I will write answers when I have time:</p><ol><li>What happens if one line has priority control while the other directly feeds the Moulding Unit, and why is that wrong?</li><li>Why must the stash be disabled?</li><li>Why does some Cuprium leak into shredding even while moulding is unblocked? Does it matter? Hint: consider phase.</li></ol></details><p>More examples:</p><p><a href="/endfield-skydoc/625-setting-adaptive-small-chubby-lung-heavy-xiranite-balancing-toy">625-Setting Adaptive Small Chubby Lung + Heavy Xiranite Balancing Toy</a></p></div>',1)])])}const m=i(a,[["render",s]]);export{h as __pageData,m as default};
